import org.eclipse.rdf4j.sail.SailException;
import org.eclipse.rdf4j.sail.base.SailSink;
import org.eclipse.rdf4j.sail.nativerdf.btree.RecordIterator;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

/**
 * Verifies that NativeSailStore wraps unexpected RuntimeExceptions in SailException so upstream callers can reliably
 * handle failures (e.g., branch flush clearing pending changes).
 *
 * The constructed TripleStore is intercepted for fault injection; the surrounding value, WAL, namespace and context
 * owners remain real. These tests exercise exception translation, not TripleStore disk correctness.
 */
public class NativeSailStoreRuntimeWrappingIT {

	File dataDir;
	TripleStore constructedTripleStore;
	NativeSailStore store;

	@BeforeEach
	public void setUp() throws Exception {
		dataDir = Files.createTempDirectory("nativestore-wrap-test").toFile();
		try (var construction = mockConstruction(TripleStore.class, (mock, context) -> {
			when(mock.getAllTriplesSortedByContext(false)).thenReturn(mock(RecordIterator.class));
		})) {
			store = new NativeSailStore(dataDir, "spoc");
			constructedTripleStore = construction.constructed().get(0);
		}
	}

	@AfterEach
	public void tearDown() throws Exception {
		if (store != null) {
			store.close();
			FileUtil.deleteDir(dataDir);
		}
	}

	@Test
	public void testFlushWrapsRuntimeIntoSailException() throws Exception {
		RuntimeException failure = new RuntimeException("simulated failure during commit");
		doThrow(failure).when(constructedTripleStore).commit();

		// Add a statement to ensure a triplestore transaction is started
		SailSink sink = store.getExplicitSailSource().sink(null);
		ValueFactory vf = store.getValueFactory();
		IRI s = vf.createIRI("urn:s");
		IRI p = vf.createIRI("urn:p");
		IRI o = vf.createIRI("urn:o");
		sink.approve(s, p, o, (Resource) null);

		// Now flush, expecting a SailException (wrapping the runtime)
		assertThatThrownBy(() -> sink.flush())
				.isInstanceOf(SailException.class)
				.hasCause(failure);
		verify(constructedTripleStore).commit();
	}

	@Test
	public void testRemoveStatementsWrapsRuntimeIntoSailException() throws Exception {
		RuntimeException failure = new RuntimeException("simulated failure during removeTriplesByContext");
		doThrow(failure).when(constructedTripleStore)
				.removeTriplesByContext(anyInt(), anyInt(), anyInt(), anyInt(), anyBoolean());

		SailSink sink = store.getExplicitSailSource().sink(null);
		// Expect SailException when attempting to remove (deprecateByQuery delegates)
		assertThatThrownBy(() -> sink.deprecateByQuery(null, null, null, new Resource[] { null }))
				.isInstanceOf(SailException.class)
				.hasCause(failure);
		verify(constructedTripleStore)
				.removeTriplesByContext(anyInt(), anyInt(), anyInt(), anyInt(), anyBoolean());
	}

}
